<?php
declare(strict_types=1);
$isHttps=isset($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!==''&&$_SERVER['HTTPS']!=='off';ini_set('session.use_strict_mode','1');session_name('coaching_tool_session');session_set_cookie_params(['httponly'=>true,'secure'=>$isHttps,'samesite'=>'Strict','path'=>'/']);session_start();header('Cache-Control: private, no-store, max-age=0');header('X-Content-Type-Options: nosniff');
require_once dirname(__DIR__).'/app/bootstrap.php';require_once dirname(__DIR__).'/app/document_storage.php';
$user=$_SESSION['user']??null;if(!is_array($user)||!in_array(($user['role']??''),['coach','client'],true)){http_response_code(403);exit('Kein Zugriff.');}
$db=coachingDatabase();
if(($user['role']??'')==='client'){$active=$db->prepare('SELECT aktiv FROM coaching_portal_zugaenge WHERE id=:id AND klient_id=:client');$active->execute(['id'=>(int)$user['id'],'client'=>(int)($user['client_id']??0)]);if((int)$active->fetchColumn()!==1){http_response_code(403);exit('Der Coachee-Zugang ist nicht aktiv.');}}
$coachId=(int)$user['id'];$clientId=(int)($user['client_id']??0);
$id=filter_var($_GET['id']??null,FILTER_VALIDATE_INT);if($id===false||$id<1){http_response_code(404);exit('Datei nicht gefunden.');}
try{if($user['role']==='coach'){$q=$db->prepare('SELECT f.speicher_schluessel,f.originalname,f.mime_typ FROM coaching_nachrichten_dateien f INNER JOIN klienten k ON k.id=f.klient_id INNER JOIN coaching_nachrichten n ON n.id=f.nachricht_id AND n.klient_id=f.klient_id AND n.coach_benutzer_id=f.coach_benutzer_id WHERE f.id=:id AND f.coach_benutzer_id=:coach AND k.benutzer_id=:owner');$q->execute(['id'=>$id,'coach'=>(int)$user['id'],'owner'=>(int)$user['id']]);}else{$q=$db->prepare("SELECT f.speicher_schluessel,f.originalname,f.mime_typ FROM coaching_nachrichten_dateien f INNER JOIN coaching_nachrichten n ON n.id=f.nachricht_id AND n.klient_id=f.klient_id AND n.coach_benutzer_id=f.coach_benutzer_id INNER JOIN coaching_auftraege a ON a.id=n.auftrag_id AND a.klient_id=n.klient_id WHERE f.id=:id AND f.klient_id=:client AND (a.status='aktiv' OR (a.status='abgeschlossen' AND a.archiv_freigegeben=1))");$q->execute(['id'=>$id,'client'=>(int)($user['client_id']??0)]);}
$f=$q->fetch(PDO::FETCH_ASSOC);if(!$f||!in_array($f['mime_typ'],['application/pdf','image/jpeg','image/png'],true)){http_response_code(404);exit('Datei nicht gefunden.');}
$path=coachingResolveDocumentFile((string)$f['speicher_schluessel'],(string)$f['mime_typ']);$name=basename(str_replace("\\",'/',(string)$f['originalname']));$name=preg_replace('/[\x00-\x1F\x7F]/u','',$name)?:'Anhang';$fallback=preg_replace('/[^A-Za-z0-9._-]/','_',$name)?:'Anhang';header('Content-Type: '.$f['mime_typ']);header('Content-Length: '.(string)filesize($path));header('Content-Disposition: attachment; filename="'.str_replace('"','',$fallback).'"; filename*=UTF-8\'\''.rawurlencode($name));readfile($path);exit;
}catch(Throwable $e){error_log('Message attachment download failed: '.$e->getMessage());http_response_code(404);exit('Datei nicht gefunden.');}
